<?php
require_once __DIR__.'/includes/bootstrap.php';$pdo=sv_next_db();$elections=sv_public_elections($pdo);$id=int_input('election_id',(int)($elections[0]['id']??0));$chosen=null;foreach($elections as $e)if((int)$e['id']===$id)$chosen=$e;
if($id&&!$chosen)sv_error_page(404,'Election unavailable','Choose a published election.',[]);
$s=$pdo->prepare("SELECT * FROM election_forum WHERE election_id=? AND status='published' ORDER BY CASE WHEN event_at IS NULL THEN 1 ELSE 0 END,event_at,id DESC");$s->execute([$id]);$items=$s->fetchAll();
$pageTitle='Candidate forum';$activeNav='guide.php';require __DIR__.'/includes/header.php';
?>
<div class="feature-page stack"><h1 class="visually-hidden">Candidate forum</h1><p>Official debates, events, and campaign resources published by election administrators.</p><form method="get" class="feature-toolbar"><label for="forum-election">Election</label><select class="input" id="forum-election" name="election_id"><?php foreach($elections as $e): ?><option value="<?= (int)$e['id'] ?>" <?= (int)$e['id']===$id?'selected':'' ?>><?= e($e['title']) ?></option><?php endforeach; ?></select><button class="btn btn--secondary">Choose election</button></form>
<?php if(!$items): ?><div class="feature-empty"><h2>No forum resources published yet</h2><p>Check again when administrators publish events or materials.</p></div><?php endif; ?>
<?php foreach($items as $item): ?><article class="feature-entry"><span class="badge badge--neutral"><?= e(['event'=>'Event','video'=>'Debate video','material'=>'Campaign material'][$item['kind']]) ?></span><h2><?= e($item['title']) ?></h2><?php if($item['event_at']): ?><p><time datetime="<?= e(to_datetime($item['event_at'])->format(DATE_ATOM)) ?>"><?= e(fmt_datetime($item['event_at'])) ?></time> · Philippine time</p><?php endif; ?><div class="feature-prose"><?= nl2br(e($item['description'])) ?></div><?php if($item['resource_url']&&sv_valid_resource_url($item['resource_url'])): ?><a class="link" href="<?= e($item['resource_url']) ?>" target="_blank" rel="noopener noreferrer">Open <?= e($item['kind']==='video'?'video':'resource') ?> (new tab)</a><?php endif; ?></article><?php endforeach; ?><a class="link" href="<?= e(url('guide.php?election_id='.$id)) ?>">Back to election guide</a></div>
<?php require __DIR__.'/includes/footer.php'; ?>
